 Ahmad","Cuttack","Cuttack","Odisha","Cuttack",null,null,"2024-05-01","Finished",9340,4670,"S R Husain"],[307,"2024-05-14","246","Common","6th","Bani Kund Imam","Banikund","Jagatsinghpur","Odisha","Bani Kund",null,null,"2024-04-29","Finished",4970,2485,"S R Husain"],[308,"2024-05-14","263","Common","6th","Bani Kund Imam","Banikund","Jagatsinghpur","Odisha","Banikund",null,null,"2024-05-29","Finished",4000,2000,"S R Husain"],[309,"2024-08-22","209","Common","6th","Ramzani","Cuttack","Cuttack","Odisha",null,null,null,"2024-07-07","Not Used",10650,0,"S R Husain"],[310,"2024-05-14","79","Common","6th","Aasik Khan","Kalinag","Jagatsinghpur","Odisha",null,null,null,"2024-04-29","Finished",5590,2795,"S R Husain"],[311,"2024-05-14","204","Common","6th","Faisal","Bihar",null,"Bihar","Bihar",null,null,"2024-04-29","Finished",1800,900,"S R Husain"],[312,"2024-05-14","244","Common","6th","Saiyed Abdul Aziz","Bhadrak","Bhadrak","Odisha","Bhadrak",null,null,"2024-04-29","Finished",5000,2500,"S R Husain"],[313,"2024-05-14","245","Common","6th","Saiyed Abdul Aziz","Basudevpur","Bhadrak","Odisha","Basudevpur",null,null,"2024-04-29","Finished",4200,2100,"S R Husain"],[314,"2024-05-14","210","Common","6th","Nizami","Denga","Jagatsinghpur","Odisha","Denga",null,null,"2024-04-29","Finished",3750,200,"S R Husain"],[315,"2024-05-14","219","Common","6th","Aasik Khan","JaH","Jagatsinghpur","Odisha","JaH",null,null,"2024-05-05","Finished",38573,0,"S R Husain"],[316,"2024-06-04","177","Common","6th","Sona Bhai","Tiran","Jagatsinghpur","Odisha","Tiran",null,null,"2024-06-04","Finished",6870,0,"S R Husain"],[317,"2024-08-22","215","Common","6th","Aasik Khan","JaH","Jagatsinghpur","Odisha","JaH",null,null,"2024-07-07","Finished",22782,0,"S R Husain"],[318,"2024-08-22","173","Common","6th","Ahmad Raza","Daryapur","Jagatsinghpur","Odisha",null,null,null,"2024-06-04","Continue",930,465,"S R Husain"],[319,"2024-08-22","163","Common","6th","Aasik Khan","JaH","Jagatsinghpur","Odisha","JaH",null,null,"2024-05-25","Finished",50505,0,"S R Husain"],[320,"2024-08-22","170","Common","6th","Hafiz Azhar","Sompur","Cuttack","Odisha",null,null,null,"2024-07-16","Finished",3000,0,"S R Husain"],[321,"2024-08-22","176","Common","6th","Mohammad Imteyaz","Goda","Jagatsinghpur","Odisha",null,null,null,"2024-07-16","Finished",2800,0,"S R Husain"],[322,"2024-08-22","175","Common","6th","Abdul Hafiz","Kalabedi","Jagatsinghpur","Odisha",null,null,null,"2024-07-16","Finished",4200,1000,"S R Husain"]]$history_rows$::jsonb) AS source(item);
  ALTER TABLE pg_temp.dms_all_history ADD PRIMARY KEY(source_row);
  IF (SELECT count(*) FROM pg_temp.dms_all_history)<>321 OR
    (SELECT sum(((original||corrections)->>'Collection Amount')::numeric) FROM pg_temp.dms_all_history)<>3582669 OR
    (SELECT sum(((original||corrections)->>'Commission Amount')::numeric) FROM pg_temp.dms_all_history)<>619227 THEN
    RAISE EXCEPTION 'Workbook row count or financial totals differ; no changes committed';
  END IF;
  FOR src IN SELECT * FROM pg_temp.dms_all_history ORDER BY source_row LOOP
    -- A source key can contribute through a real receipt OR the recorded history, never both.
    IF EXISTS (SELECT 1 FROM public.legacy_collection_imports l
      WHERE l.source_key='Book3_v1:Sheet1:'||src.source_row::text AND l.status='IMPORTED') THEN CONTINUE; END IF;
    INSERT INTO public.legacy_collection_imports(source_key,source_row,source_hash,source_data,reason)
    VALUES('Book3_v1:Sheet1:'||src.source_row::text,src.source_row,
      encode(sha256(convert_to(src.original::text,'UTF8')),'hex'),src.original,'Historical collection recorded')
      ON CONFLICT(source_key) DO NOTHING;
    SELECT l.source_data||coalesce(l.source_corrections,'{}'::jsonb)||src.original||src.corrections
      INTO effective FROM public.legacy_collection_imports l
      WHERE l.source_key='Book3_v1:Sheet1:'||src.source_row::text;
    entry_day:=NULL; collection_day:=NULL; reason_text:='';
    BEGIN
      IF effective->>'Entry Date' ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}' THEN entry_day:=left(effective->>'Entry Date',10)::date; END IF;
    EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow THEN entry_day:=NULL; END;
    BEGIN
      IF effective->>'Collection Date' ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}' THEN collection_day:=left(effective->>'Collection Date',10)::date; END IF;
    EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow THEN collection_day:=NULL; END;
    IF entry_day IS NULL THEN reason_text:='Entry date not recorded or invalid. '; END IF;
    IF collection_day IS NULL THEN reason_text:=reason_text||'Collection date not recorded or invalid. '; END IF;
    history_kind:=CASE lower(btrim(effective->>'Type')) WHEN 'common' THEN 'REGULAR'
      WHEN 't10' THEN 'TOKEN' WHEN 't50' THEN 'TOKEN' WHEN 't100' THEN 'TOKEN' ELSE 'UNKNOWN' END;
    token_paise:=CASE lower(btrim(effective->>'Type')) WHEN 't10' THEN 1000 WHEN 't50' THEN 5000 WHEN 't100' THEN 10000 END;
    edition_no:=substring(effective->>'Edition' from '^[0-9]+')::integer;
    original_book:=CASE WHEN effective->>'Book No.' ~ '^[0-9]{1,9}$' THEN (effective->>'Book No.')::integer END;
    SELECT count(*),(array_agg(p.id))[1] INTO matches,person_uuid
      FROM public.people p JOIN public.fundraisers f ON f.person_id=p.id
      WHERE p.role='COLLECTOR' AND p.deleted_at IS NULL AND f.deleted_at IS NULL
        AND lower(regexp_replace(btrim(p.full_name),'[[:space:]]+',' ','g'))=
          lower(regexp_replace(btrim(effective->>'Fundraiser Name'),'[[:space:]]+',' ','g'));
    IF matches<>1 THEN person_uuid:=NULL; reason_text:=reason_text||'Fundraiser link not recorded. '; END IF;
    SELECT count(*),(array_agg(m.id))[1] INTO matches,edition_uuid FROM public.master_records m
      WHERE m.kind='EDITION' AND m.deleted_at IS NULL AND m.edition_number=edition_no
        AND m.edition_book_type=history_kind AND m.edition_token_value_paise IS NOT DISTINCT FROM token_paise;
    IF matches<>1 THEN edition_uuid:=NULL; reason_text:=reason_text||'Edition link not recorded. '; END IF;
    stock_uuid:=NULL;
    -- Reuse an existing reviewed book allocation for this original reference and same canonical person.
    SELECT count(DISTINCT l.book_id),(array_agg(l.book_id))[1] INTO matches,stock_uuid
      FROM public.legacy_collection_imports l JOIN public.books b ON b.id=l.book_id AND b.deleted_at IS NULL
      WHERE l.status='IMPORTED' AND l.source_key LIKE 'Book3_v1:Sheet1:%'
        AND l.person_id=person_uuid AND b.book_type=history_kind
        AND b.token_value_paise IS NOT DISTINCT FROM token_paise
        AND (edition_no IS NULL OR b.edition_number=edition_no)
        AND (edition_uuid IS NULL OR b.edition_id=edition_uuid)
        AND (l.source_data||coalesce(l.source_corrections,'{}'::jsonb))->>'Book No.'=original_book::text;
    IF matches<>1 THEN stock_uuid:=NULL; END IF;
    IF stock_uuid IS NULL AND edition_uuid IS NOT NULL THEN
      SELECT count(*),(array_agg(b.id))[1] INTO matches,stock_uuid FROM public.books b
        JOIN public.master_records m ON m.id=b.edition_id
        WHERE b.edition_id=edition_uuid AND b.deleted_at IS NULL AND
          CASE WHEN history_kind='TOKEN' THEN b.edition_book_number=original_book ELSE
            b.receipt_from=CASE WHEN edition_no<=5 THEN 1+(original_book::bigint-1)*50
              ELSE m.pages_from+(original_book::bigint-1)*50 END END;
      IF matches<>1 THEN stock_uuid:=NULL; END IF;
    END IF;
    IF stock_uuid IS NOT NULL THEN SELECT edition_id INTO edition_uuid FROM public.books WHERE id=stock_uuid; END IF;
    IF stock_uuid IS NULL THEN reason_text:=reason_text||'Original book reference retained without an assumed stock assignment. '; END IF;
    UPDATE public.legacy_collection_imports SET status='RECORDED',person_id=person_uuid,book_id=stock_uuid,
      assignment_id=NULL,return_id=NULL,receipt_id=NULL,assumed_receipt_number=NULL,
      source_corrections=coalesce(source_corrections,'{}'::jsonb)||effective||
        jsonb_build_object('_recordedHistory',jsonb_build_object(
          'entryDate',entry_day,'collectionDate',collection_day,'editionId',edition_uuid,
          'bookType',history_kind,'tokenValuePaise',token_paise,
          'workbook','Money Receipt Data Entry-fundraisers correction.xlsm + corrected 84 rows')),
      reason='Recorded historical collection; missing fields accepted. '||reason_text,imported_at=coalesce(imported_at,now())
      WHERE source_key='Book3_v1:Sheet1:'||src.source_row::text AND status<>'IMPORTED';
  END LOOP;
  IF EXISTS (SELECT 1 FROM pg_temp.dms_all_history source_snapshot
    LEFT JOIN public.legacy_collection_imports l ON l.source_key='Book3_v1:Sheet1:'||source_snapshot.source_row::text
    WHERE l.source_key IS NULL OR l.status NOT IN ('IMPORTED','RECORDED')) THEN
    RAISE EXCEPTION 'A source row was not recorded; the transaction has been rolled back';
  END IF;
END;
$record_history$;

CREATE INDEX IF NOT EXISTS legacy_recorded_history_idx ON public.legacy_collection_imports(person_id,book_id) WHERE status='RECORDED';
DROP POLICY IF EXISTS recorded_history_staff_read ON public.legacy_collection_imports;
CREATE POLICY recorded_history_staff_read ON public.legacy_collection_imports FOR SELECT TO dms_runtime
  USING(status IN ('RECORDED','IMPORTED') AND current_setting('app.role',true) IN ('SUPER_ADMIN','ADMIN') AND EXISTS (
    SELECT 1 FROM public.people viewer WHERE viewer.id::text=current_setting('app.person_id',true)
      AND viewer.auth_user_id::text=current_setting('app.auth_user_id',true)
      AND viewer.role=current_setting('app.role',true) AND viewer.status='ACTIVE' AND viewer.deleted_at IS NULL));

-- Read-only projection. SECURITY INVOKER preserves the ledger's existing role/RLS restrictions.
CREATE OR REPLACE FUNCTION public.recorded_historical_collections()
RETURNS TABLE(source_key text,source_row integer,person_id uuid,book_id uuid,edition_id uuid,book_type text,
  token_value_paise integer,fundraiser_name text,fundraiser_code text,book_number text,edition_name text,
  collection_date date,collection_area text,book_condition text,amount_paise bigint,commission_paise bigint,missing_details text)
LANGUAGE sql STABLE SECURITY INVOKER SET search_path=pg_catalog,public AS $recorded$
  WITH history AS (
    SELECT l.*,l.source_data||coalesce(l.source_corrections,'{}'::jsonb) AS effective
    FROM public.legacy_collection_imports l WHERE l.status='RECORDED'
      AND current_setting('app.role',true) IN ('SUPER_ADMIN','ADMIN')
  )
  SELECT h.source_key,h.source_row,h.person_id,h.book_id,
    (h.effective->'_recordedHistory'->>'editionId')::uuid,
    coalesce(h.effective->'_recordedHistory'->>'bookType','UNKNOWN'),
    (h.effective->'_recordedHistory'->>'tokenValuePaise')::integer,
    coalesce(nullif(h.effective->>'Fundraiser Name',''),'Not recorded'),coalesce(f.code,''),
    coalesce(nullif(h.effective->>'Book No.',''),'Not recorded'),
    coalesce(nullif(h.effective->>'Edition',''),'Not recorded'),
    (h.effective->'_recordedHistory'->>'collectionDate')::date,
    coalesce(h.effective->>'Collection Area',''),
    coalesce(nullif(h.effective->>'Book Condition',''),'Blank'),
    ((h.effective->>'Collection Amount')::numeric*100)::bigint,
    ((h.effective->>'Commission Amount')::numeric*100)::bigint,h.reason
  FROM history h LEFT JOIN public.fundraisers f ON f.person_id=h.person_id AND f.deleted_at IS NULL;
$recorded$;
REVOKE ALL ON FUNCTION public.recorded_historical_collections() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.recorded_historical_collections() TO dms_runtime;

CREATE OR REPLACE FUNCTION public.historical_collection_date(value text) RETURNS date
LANGUAGE plpgsql IMMUTABLE STRICT SECURITY INVOKER SET search_path=pg_catalog AS $history_date$
BEGIN
  IF btrim(value) ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}' THEN RETURN left(btrim(value),10)::date; END IF;
  RETURN NULL;
EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow THEN RETURN NULL;
END;
$history_date$;
REVOKE ALL ON FUNCTION public.historical_collection_date(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.historical_collection_date(text) TO dms_runtime;

-- Display ALL source rows. Financial totals above still use RECORDED rows only,
-- so a linked historical receipt is never counted twice.
CREATE OR REPLACE FUNCTION public.all_historical_collection_rows()
RETURNS TABLE(source_key text,source_row integer,person_id uuid,book_id uuid,edition_id uuid,book_type text,
  token_value_paise integer,fundraiser_name text,fundraiser_code text,book_number text,original_book text,edition_name text,
  receipt_from integer,receipt_to integer,collection_date date,collection_area text,book_condition text,
  amount_paise bigint,commission_paise bigint,assignment_id uuid,return_id uuid,receipt_number integer,link_status text)
LANGUAGE sql STABLE SECURITY INVOKER SET search_path=pg_catalog,public AS $all_history$
  WITH history AS (
    SELECT l.*,l.source_data||coalesce(l.source_corrections,'{}'::jsonb) AS effective
    FROM public.legacy_collection_imports l WHERE l.status IN ('IMPORTED','RECORDED')
      AND l.source_key LIKE 'Book3_v1:Sheet1:%'
      AND current_setting('app.role',true) IN ('SUPER_ADMIN','ADMIN')
  )
  SELECT h.source_key,h.source_row,CASE WHEN f.id IS NOT NULL THEN p.id END,b.id,edition.id,
    coalesce(b.book_type,h.effective->'_recordedHistory'->>'bookType',
      CASE lower(h.effective->>'Type') WHEN 'common' THEN 'REGULAR'
        WHEN 't10' THEN 'TOKEN' WHEN 't50' THEN 'TOKEN' WHEN 't100' THEN 'TOKEN' ELSE 'UNKNOWN' END),
    coalesce(b.token_value_paise,(h.effective->'_recordedHistory'->>'tokenValuePaise')::integer,
      CASE lower(h.effective->>'Type') WHEN 't10' THEN 1000 WHEN 't50' THEN 5000 WHEN 't100' THEN 10000 END),
    coalesce(p.full_name,nullif(h.effective->>'Fundraiser Name',''),'N/A'),coalesce(f.code,'N/A'),
    coalesce(b.book_number,nullif(h.effective->>'Book No.',''),'N/A'),
    coalesce(nullif(h.effective->>'Book No.',''),'N/A'),
    coalesce(edition.name_en,nullif(h.effective->>'Edition',''),'N/A'),b.receipt_from,b.receipt_to,
    public.historical_collection_date(h.effective->>'Collection Date'),
    coalesce(nullif(h.effective->>'Collection Area',''),'N/A'),
    coalesce(nullif(h.effective->>'Book Condition',''),'N/A'),
    ((h.effective->>'Collection Amount')::numeric*100)::bigint,
    ((h.effective->>'Commission Amount')::numeric*100)::bigint,
    assigned.id,returned.id,h.assumed_receipt_number,
    CASE WHEN assigned.id IS NOT NULL AND returned.id IS NOT NULL THEN 'LINKED' ELSE 'RECORDED' END
  FROM history h
    LEFT JOIN public.people p ON p.id=h.person_id AND p.role='COLLECTOR' AND p.deleted_at IS NULL
    LEFT JOIN public.fundraisers f ON f.person_id=p.id AND f.deleted_at IS NULL
    LEFT JOIN public.books b ON b.id=h.book_id AND b.deleted_at IS NULL
    LEFT JOIN public.master_records edition ON edition.id=coalesce(b.edition_id,
      (h.effective->'_recordedHistory'->>'editionId')::uuid) AND edition.deleted_at IS NULL
    LEFT JOIN public.book_assignments assigned ON assigned.id=h.assignment_id AND assigned.deleted_at IS NULL
    LEFT JOIN public.book_returns returned ON returned.id=h.return_id AND returned.deleted_at IS NULL
      AND returned.assignment_id=assigned.id AND returned.book_id=b.id;
$all_history$;
REVOKE ALL ON FUNCTION public.all_historical_collection_rows() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.all_historical_collection_rows() TO dms_runtime;

-- This matches the same valid-receipt/exact-commission calculation used by the UI.
WITH submissions AS (
  SELECT r.id,sum(receipt.amount_paise) AS collected,
    coalesce(max(r.historical_commission_paise),
      round(sum(receipt.amount_paise)::numeric*r.commission_basis_points/1000000)*100) AS commission
  FROM public.book_returns r JOIN public.books b ON b.id=r.book_id AND b.deleted_at IS NULL
    JOIN public.master_records m ON m.id=b.edition_id AND m.deleted_at IS NULL AND m.kind='EDITION'
    JOIN public.book_receipts receipt ON receipt.return_id=r.id AND receipt.book_id=b.id
      AND receipt.deleted_at IS NULL AND receipt.status='VALID'
  WHERE r.deleted_at IS NULL GROUP BY r.id,r.commission_basis_points
), combined AS (
  SELECT collected,commission FROM submissions
  UNION ALL SELECT coalesce(amount_paise,0),coalesce(commission_paise,0) FROM public.recorded_historical_collections()
), totals AS (SELECT coalesce(sum(collected),0) AS collected,coalesce(sum(commission),0) AS commission FROM combined)
SELECT 321 AS workbook_rows,3582669 AS workbook_collection_inr,619227 AS workbook_commission_inr,
  (SELECT count(*) FROM public.legacy_collection_imports WHERE source_key LIKE 'Book3_v1:Sheet1:%' AND status='IMPORTED') AS linked_rows,
  (SELECT count(*) FROM public.recorded_historical_collections()) AS recorded_historical_rows,
  (SELECT jsonb_build_object('rows',count(*),'fundraiserLinked',count(person_id),
    'editionLinked',count(edition_id),'bookAndRangeLinked',count(book_id),'assignmentAndSubmissionLinked',
    count(*) FILTER(WHERE assignment_id IS NOT NULL AND return_id IS NOT NULL))
    FROM public.all_historical_collection_rows()) AS core_link_counts,
  (SELECT coalesce(jsonb_agg(jsonb_build_object('excelRow',source_row,'fundraiser',fundraiser_name,
    'book',original_book,'edition',edition_name,'missingLinks',concat_ws(', ',
      CASE WHEN person_id IS NULL THEN 'fundraiser' END,CASE WHEN edition_id IS NULL THEN 'edition' END,
      CASE WHEN book_id IS NULL THEN 'book/receipt range' END)) ORDER BY source_row),'[]'::jsonb)
    FROM public.all_historical_collection_rows() WHERE person_id IS NULL OR edition_id IS NULL OR book_id IS NULL) AS missing_core_links,
  collected/100.0 AS app_collection_inr,commission/100.0 AS app_commission_inr,
  (collected-358266900)/100.0 AS collection_difference_inr,
  (commission-61922700)/100.0 AS commission_difference_inr
FROM totals;
COMMIT;

